/* Claude Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Claude Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 47.95 50.03% 96.36%;
    --foreground: 47.97 22.73% 19.33%;
    --card: 47.95 50.03% 96.36%;
    --card-foreground: 330 0% 7.73%;
    --popover: 300 50% 100%;
    --popover-foreground: 50.77 19.5% 13.37%;
    --primary: 15.13 56.98% 52.62%;
    --primary-foreground: 300 50% 100%;
    --secondary: 46.18 16.2% 88.6%;
    --secondary-foreground: 50.71 9.79% 29.43%;
    --muted: 43.98 35.12% 89.03%;
    --muted-foreground: 49.95 3.17% 50.43%;
    --accent: 46.18 16.2% 88.6%;
    --accent-foreground: 50.77 19.5% 13.37%;
    --destructive: 330 0% 7.73%;
    --destructive-foreground: 300 50% 100%;
    --border: 49.95 10.33% 83.39%;
    --input: 50.7 10.06% 67.33%;
    --ring: 209.63 78.55% 48.81%;
    --chart-1: 18.36 58.35% 43.96%;
    --chart-2: 251.53 86.2% 74.67%;
    --chart-3: 46.14 29.97% 81.52%;
    --chart-4: 256.55 47.43% 88.12%;
    --chart-5: 17.61 57.23% 44.35%;
    --radius: 0.5rem;
    --sidebar: 51.4 34.17% 94.98%;
    --sidebar-foreground: 59.69 5.1% 22.96%;
    --sidebar-primary: 15.13 56.98% 52.62%;
    --sidebar-primary-foreground: 300 0% 98.68%;
    --sidebar-accent: 46.18 16.2% 88.6%;
    --sidebar-accent-foreground: 300 0% 20.89%;
    --sidebar-border: 330 0% 92.15%;
    --sidebar-ring: 0 0% 70.6%;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 300 0% 15.03%;
    --foreground: 46.19 7.06% 74.64%;
    --card: 300 0% 15.03%;
    --card-foreground: 47.95 50.03% 96.36%;
    --popover: 320 0% 18.9%;
    --popover-foreground: 0 0% 89.56%;
    --primary: 14.77 62.2% 59.32%;
    --primary-foreground: 300 50% 100%;
    --secondary: 47.95 50.03% 96.36%;
    --secondary-foreground: 320 0% 18.9%;
    --muted: 300 0% 10.4%;
    --muted-foreground: 51.38 10.36% 68.53%;
    --accent: 47.92 14.37% 8.78%;
    --accent-foreground: 51.4 34.17% 94.98%;
    --destructive: 359.91 86.11% 60.55%;
    --destructive-foreground: 300 50% 100%;
    --border: 60 5.08% 22.96%;
    --input: 52.54 4.55% 30.33%;
    --ring: 209.63 78.55% 48.81%;
    --chart-1: 18.36 58.35% 43.96%;
    --chart-2: 251.53 86.2% 74.67%;
    --chart-3: 47.92 14.37% 8.78%;
    --chart-4: 248.09 24.31% 22.71%;
    --chart-5: 17.61 57.23% 44.35%;
    --radius: 0.5rem;
    --sidebar: 330 0% 12.22%;
    --sidebar-foreground: 46.19 7.06% 74.64%;
    --sidebar-primary: 300 0% 20.89%;
    --sidebar-primary-foreground: 300 0% 98.68%;
    --sidebar-accent: 330 0% 6.02%;
    --sidebar-accent-foreground: 46.19 7.06% 74.64%;
    --sidebar-border: 330 0% 92.15%;
    --sidebar-ring: 0 0% 70.6%;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  }

}
